  1	import java.util.ArrayList;
  2	import java.util.Arrays;
  3	import java.util.Comparator;
  4	import java.util.List;
  5	import java.util.Objects;
  6	import java.util.PriorityQueue;
  7	
  8	public class HuffmanCoding {
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	    private static final String SAMPLE_SYMBOLS = "abcdef";
 11	    private static final int[] SAMPLE_FREQUENCIES = {5, 9, 12, 13, 16, 45};
 12	
 13	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 14	        validateSymbols(symbols);
 15	        validateFrequencyCount(symbols.length(), frequencies);
 16	        return HuffmanTree.fromFrequencies(frequencies)
 17	                .buildCodebook(symbols.length())
 18	                .inTraversalOrder();
 19	    }
 20	
 21	    static ArrayList<String> huffmanCodes(int[] frequencies) {
 22	        validateFrequencies(frequencies);
 23	        return HuffmanTree.fromFrequencies(frequencies)
 24	                .buildCodebook(frequencies.length)
 25	                .inTraversalOrder();
 26	    }
 27	
 28	    static ArrayList<String> huffmanCodesBySymbolOrder(String symbols, int[] frequencies) {
 29	        validateSymbols(symbols);
 30	        validateFrequencyCount(symbols.length(), frequencies);
 31	        return HuffmanTree.fromFrequencies(frequencies)
 32	                .buildCodebook(symbols.length())
 33	                .inSymbolOrder();
 34	    }
 35	
 36	    private static void validateSymbols(String symbols) {
 37	        Objects.requireNonNull(symbols, "symbols must not be null");
 38	    }
 39	
 40	    private static void validateFrequencies(int[] frequencies) {
 41	        Objects.requireNonNull(frequencies, "frequencies must not be null");
 42	        for (int frequency : frequencies) {
 43	            if (frequency < 0) {
 44	                throw new IllegalArgumentException("frequencies must be non-negative");
 45	            }
 46	        }
 47	    }
 48	
 49	    private static void validateFrequencyCount(int symbolCount, int[] frequencies) {
 50	        validateFrequencies(frequencies);
 51	        if (symbolCount != frequencies.length) {
 52	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
 53	        }
 54	    }
 55	
 56	    private static void printCodes(List<String> codes) {
 57	        System.out.print(String.join(" ", codes));
 58	    }
 59	
 60	    public static void main(String[] args) {
 61	        ArrayList<String> codes = huffmanCodes(SAMPLE_SYMBOLS, SAMPLE_FREQUENCIES);
 62	        printCodes(codes);
 63	    }
 64	
 65	    private static final class HuffmanTree {
 66	        private static final Comparator<Node> NODE_ORDER =
 67	                Comparator.comparingInt((Node node) -> node.frequency)
 68	                        .thenComparingInt(node -> node.sortOrder);
 69	
 70	        private final Node root;
 71	
 72	        private HuffmanTree(Node root) {
 73	            this.root = root;
 74	        }
 75	
 76	        private static HuffmanTree fromFrequencies(int[] frequencies) {
 77	            if (frequencies.length == 0) {
 78	                return new HuffmanTree(null);
 79	            }
 80	
 81	            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
 82	            for (int i = 0; i < frequencies.length; i++) {
 83	                queue.add(new Node(frequencies[i], i));
 84	            }
 85	
 86	            while (queue.size() > 1) {
 87	                Node left = queue.poll();
 88	                Node right = queue.poll();
 89	                queue.add(new Node(left, right));
 90	            }
 91	
 92	            return new HuffmanTree(queue.peek());
 93	        }
 94	
 95	        private Codebook buildCodebook(int symbolCount) {
 96	            if (symbolCount == 0) {
 97	                return new Codebook(0);
 98	            }
 99	
100	            Codebook codebook = new Codebook(symbolCount);
101	            collectCodes(root, new StringBuilder(), codebook);
102	            return codebook;
103	        }
104	
105	        private void collectCodes(Node node, StringBuilder path, Codebook codebook) {
106	            if (node == null) {
107	                return;
108	            }
109	
110	            if (node.isLeaf()) {
111	                codebook.add(node.symbolIndex, path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
112	                return;
113	            }
114	
115	            path.append('0');
116	            collectCodes(node.left, path, codebook);
117	            path.deleteCharAt(path.length() - 1);
118	
119	            path.append('1');
120	            collectCodes(node.right, path, codebook);
121	            path.deleteCharAt(path.length() - 1);
122	        }
123	
124	        private static final class Codebook {
125	            private final ArrayList<String> traversalCodes = new ArrayList<>();
126	            private final String[] symbolCodes;
127	
128	            private Codebook(int symbolCount) {
129	                symbolCodes = new String[symbolCount];
130	            }
131	
132	            private void add(int symbolIndex, String code) {
133	                traversalCodes.add(code);
134	                symbolCodes[symbolIndex] = code;
135	            }
136	
137	            private ArrayList<String> inTraversalOrder() {
138	                return new ArrayList<>(traversalCodes);
139	            }
140	
141	            private ArrayList<String> inSymbolOrder() {
142	                return new ArrayList<>(Arrays.asList(symbolCodes));
143	            }
144	        }
145	
146	        private static final class Node {
147	            private final int frequency;
148	            private final int sortOrder;
149	            private final int symbolIndex;
150	            private final Node left;
151	            private final Node right;
152	
153	            private Node(int frequency, int symbolIndex) {
154	                this(frequency, symbolIndex, symbolIndex, null, null);
155	            }
156	
157	            private Node(Node left, Node right) {
158	                this(
159	                        left.frequency + right.frequency,
160	                        Math.min(left.sortOrder, right.sortOrder),
161	                        -1,
162	                        left,
163	                        right
164	                );
165	            }
166	
167	            private Node(int frequency, int sortOrder, int symbolIndex, Node left, Node right) {
168	                this.frequency = frequency;
169	                this.sortOrder = sortOrder;
170	                this.symbolIndex = symbolIndex;
171	                this.left = left;
172	                this.right = right;
173	            }
174	
175	            private boolean isLeaf() {
176	                return left == null && right == null;
177	            }
178	        }
179	    }
180	}

