 4	public class HuffmanCodingTest {
 5	    public static void main(String[] args) {
 6	        shouldGenerateExpectedTraversalOrderCodes();
 7	        shouldGenerateExpectedSymbolOrderCodes();
 8	        shouldHandleSingleSymbol();
 9	        shouldHandleEmptyInput();
10	        shouldRejectNullFrequencies();
11	        shouldRejectNegativeFrequencies();
12	        shouldRejectMismatchedInputLengths();
13	    }
14	
15	    private static void shouldGenerateExpectedTraversalOrderCodes() {
16	        assertListEquals(
17	                Arrays.asList("0", "100", "101", "1100", "1101", "111"),
18	                HuffmanCoding.huffmanCodes("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
19	                "legacy API should preserve traversal-order output"
20	        );
21	    }
22	
23	    private static void shouldGenerateExpectedSymbolOrderCodes() {
24	        assertListEquals(
25	                Arrays.asList("1100", "1101", "100", "101", "111", "0"),
26	                HuffmanCoding.huffmanCodesBySymbolOrder("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
27	                "symbol-order API should align codes with the input symbol positions"
28	        );
29	    }
30	
31	    private static void shouldHandleSingleSymbol() {
32	        assertListEquals(
33	                Arrays.asList("0"),
34	                HuffmanCoding.huffmanCodes(new int[]{7}),
35	                "single symbol should be encoded as 0"
36	        );
37	    }
38	
39	    private static void shouldHandleEmptyInput() {
40	        assertListEquals(
41	                Arrays.asList(),
42	                HuffmanCoding.huffmanCodes(new int[]{}),
43	                "empty input should produce no codes"
44	        );
45	    }
46	
47	    private static void shouldRejectMismatchedInputLengths() {
48	        assertThrows(
49	                IllegalArgumentException.class,
50	                () -> HuffmanCoding.huffmanCodes("ab", new int[]{1}),
51	                "mismatched symbols and frequencies should be rejected"
52	        );
53	    }
54	
55	    private static void shouldRejectNullFrequencies() {
56	        assertThrows(
57	                NullPointerException.class,
58	                () -> HuffmanCoding.huffmanCodes((int[]) null),
59	                "null frequencies should be rejected"
60	        );
61	    }
62	
63	    private static void shouldRejectNegativeFrequencies() {
64	        assertThrows(
65	                IllegalArgumentException.class,
66	                () -> HuffmanCoding.huffmanCodes(new int[]{2, -1, 3}),
67	                "negative frequencies should be rejected"
68	        );
69	    }
