71	    private static void assertListEquals(List<String> expected, List<String> actual, String message) {
72	        if (!expected.equals(actual)) {
73	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
74	        }
75	    }
76	
77	    private static void assertThrows(
78	            Class<? extends Throwable> expectedType,
79	            ThrowingRunnable action,
80	            String message
81	    ) {
82	        try {
83	            action.run();
84	        } catch (Throwable error) {
85	            if (expectedType.isInstance(error)) {
86	                return;
87	            }
88	            throw new AssertionError(message + ": expected " + expectedType.getSimpleName()
89	                    + " but got " + error.getClass().getSimpleName(), error);
90	        }
91	
92	        throw new AssertionError(message + ": expected " + expectedType.getSimpleName());
93	    }
94	
95	    @FunctionalInterface
96	    private interface ThrowingRunnable {
97	        void run();
98	    }
99	}
